update public.notifications
set created_at = now() - (random() * interval '10 days'), is_read = random() < 0.6
where created_at = now() and recipient_id in ('5eed0000-0000-4000-8000-000000000001', '5eed0000-0000-4000-8000-000000000003', '5eed0000-0000-4000-8000-000000000004', '5eed0000-0000-4000-8000-000000000005', '5eed0000-0000-4000-8000-000000000006', '5eed0000-0000-4000-8000-000000000007', '5eed0000-0000-4000-8000-000000000008', '5eed0000-0000-4000-8000-000000000009', '5eed0000-0000-4000-8000-00000000000a', '5eed0000-0000-4000-8000-00000000000b', '5eed0000-0000-4000-8000-00000000000c', '5eed0000-0000-4000-8000-00000000000d', '5eed0000-0000-4000-8000-00000000000e', '5eed0000-0000-4000-8000-00000000000f', '5eed0000-0000-4000-8000-000000000010', '5eed0000-0000-4000-8000-000000000011', '5eed0000-0000-4000-8000-000000000012');
select content_type as tur, count(*) as prompt, count(*) filter (where exists (select 1 from public.prompt_media m where m.prompt_id = p.id)) as kapakli, count(*) filter (where exists (select 1 from public.prompt_results r where r.prompt_id = p.id)) as sonuclu from public.prompts p where p.id::text like '5eed0003-%' group by 1 order by 1;
commit;
